<?php /** @var list<array<string,mixed>> $versions */ /** @var bool $restriction */ ?>
<div class="page-head"><div><p class="eyebrow">Compliance &amp; legal</p><h1>Policy acceptance</h1></div><a class="btn btn-ghost" href="/admin/compliance">&larr; Compliance &amp; legal</a></div>
<p class="muted">When you publish a <strong>material</strong> version of a document that needs acceptance, every active client is emailed and must accept it by the deadline. <?= $restriction ? 'After the deadline (or if they refuse) a client\'s dashboard is restricted: they keep read access to their legal and financial records and can contact us. Nothing is deleted.' : 'Restriction after the deadline is switched OFF (Compliance & legal → Policy acceptance).' ?></p>
<div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Document</th><th>Version</th><th>Published</th><th>Deadline</th><th>Accepted</th><th>Pending</th><th>Declined</th><th></th></tr></thead><tbody>
<?php foreach ($versions as $v) : ?><tr><td><?= e($v['doc_title']) ?></td><td>v<?= e($v['version_no']) ?><?= $v['status'] === 'superseded' ? ' <span class="muted">(replaced)</span>' : '' ?></td><td><?= e(local_time($v['published_at'])) ?></td>
    <td><?= $v['accept_by'] ? e(local_date((string) $v['accept_by'])) . ($v['overdue'] ? ' <span class="badge badge-d-cancelled">passed</span>' : '') : '—' ?></td><td><?= e($v['accepted']) ?></td><td><?= e($v['pending']) ?></td><td><?= e($v['declined']) ?></td><td><a href="/admin/compliance/acceptance/<?= e($v['id']) ?>">Open</a></td></tr><?php endforeach; ?>
